import React from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import api from '../api/axios';
import '../styles/home.css';

function avatarUrl(name, bg) {
  const encoded = encodeURIComponent(name);
  return `https://ui-avatars.com/api/?name=${encoded}&background=${bg}&color=fff&bold=true&size=128`;
}

const samplePosts = [
  { id: 1, author: 'Maya Santos', color: '3B5BDB', time: '2h', text: 'Finished my cybersecurity project presentation today! 🎉', likes: 24, comments: 5 },
  { id: 2, author: 'Jordan Cruz', color: '42B72A', time: '5h', text: 'Anyone else up late studying for the networks exam?', likes: 11, comments: 9 },
  { id: 3, author: 'Priya Nair', color: 'F0902F', time: '1d', text: 'Great workshop on web app security this week.', likes: 42, comments: 13 },
];

export default function Home() {
  const { user, logout } = useAuth();
  const navigate = useNavigate();

  const handleLogout = async () => {
    try { await api.post('/logout'); } catch (e) { /* ignore */ }
    logout();
    navigate('/login');
  };

  const userFullName = `${user?.first_name || ''} ${user?.last_name || ''}`.trim() || 'You';

  return (
    <div className="home-page">
      <nav className="home-nav">
        <div className="nav-logo" onClick={() => navigate('/home')}>PHISHBOOK</div>
        <div className="nav-links">
          <span className="nav-essential" onClick={() => navigate('/home')}>Home</span>
          <span>Search</span>
          <span>Notifications</span>
          <span className="nav-essential" onClick={() => navigate('/profile')}>Profile</span>
          <button className="nav-logout" onClick={handleLogout}>Logout</button>
        </div>
      </nav>

      <div className="home-body">
        <aside className="sidebar left">
          <div className="profile-chip" onClick={() => navigate('/profile')}>
            <img className="avatar" src={avatarUrl(userFullName, '3B5BDB')} alt={userFullName} />
            <span>{userFullName}</span>
          </div>
          <ul>
            <li>👥 Friends</li>
            <li>🧑‍🤝‍🧑 Groups</li>
            <li>🔖 Saved</li>
            <li>🕰️ Memories</li>
          </ul>
        </aside>

        <main className="feed">
          <div className="create-post">
            <img className="avatar" src={avatarUrl(userFullName, '3B5BDB')} alt={userFullName} />
            <input placeholder={`What's on your mind, ${user?.first_name || ''}?`} readOnly />
          </div>

          {samplePosts.map((post) => (
            <div className="post-card" key={post.id}>
              <div className="post-header">
                <img className="avatar" src={avatarUrl(post.author, post.color)} alt={post.author} />
                <div>
                  <div className="post-author">{post.author}</div>
                  <div className="post-time">{post.time} &middot; 🌐 Public</div>
                </div>
              </div>
              <p className="post-text">{post.text}</p>
              <div className="post-actions">
                <span>👍 Like ({post.likes})</span>
                <span>💬 Comment ({post.comments})</span>
                <span>↗ Share</span>
              </div>
            </div>
          ))}
        </main>

        <aside className="sidebar right">
          <h4>Suggested Friends</h4>
          <ul>
            <li><img className="avatar" style={{ width: 28, height: 28 }} src={avatarUrl('Alex Rivera', '9b59b6')} alt="Alex Rivera" /> Alex Rivera</li>
            <li><img className="avatar" style={{ width: 28, height: 28 }} src={avatarUrl('Sam Oduya', 'e67e22')} alt="Sam Oduya" /> Sam Oduya</li>
            <li><img className="avatar" style={{ width: 28, height: 28 }} src={avatarUrl('Lin Zhao', '16a085')} alt="Lin Zhao" /> Lin Zhao</li>
          </ul>
          <h4>Trending Topics</h4>
          <ul>
            <li>#CyberSecurityClass</li>
            <li>#WebDev2026</li>
            <li>#CapstoneProjects</li>
          </ul>
        </aside>
      </div>
    </div>
  );
}
